html { font-size: 100%; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
  line-height: 1.6;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: var(--color-primary-text);
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Layout ─────────────────────────────────────────────────── */
main {
  max-width: 680px;
  margin: 0 auto;
}

/* ── Page header ────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2rem;
}
.page-header__eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: rgba(79,110,247,.1);
  padding: .25rem .75rem;
  border-radius: 999px;
  margin-bottom: .75rem;
}
.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--color-text);
  letter-spacing: -.02em;
}
.page-header__sub {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: .95rem;
}

/* ── Quiz form ──────────────────────────────────────────────── */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Form field card ────────────────────────────────────────── */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 1.5rem 1.75rem;
  transition: border-color var(--transition);
}
.form-field:focus-within {
  border-color: var(--color-border-focus);
}
.form-field--error {
  border-color: var(--color-error-border);
  background: var(--color-error-bg);
}

/* ── Fieldset / legend ──────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}
legend {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: .25rem;
  line-height: 1.4;
  float: left;          /* fix legend inline-block sizing in some browsers */
  width: 100%;
}
legend + * { clear: both; }

.question-number {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: .4rem;
}

/* ── Help & error text ──────────────────────────────────────── */
.help-text {
  font-size: .85rem;
  color: var(--color-help);
  margin-bottom: 1rem;
  line-height: 1.5;
}
.error-text {
  font-size: .85rem;
  color: var(--color-error);
  font-weight: 600;
  margin-top: .75rem;
  display: flex;
  align-items: flex-start;
  gap: .35rem;
}
.error-text::before {
  content: "⚠";
  flex-shrink: 0;
  margin-top: .05em;
}
[hidden] { display: none !important; }

/* ── Checkbox options list ──────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  margin-top: .85rem;
}

/* ── Checkbox option row ────────────────────────────────────── */
.option {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .65rem .9rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  user-select: none;
}
.option:hover {
  background: rgba(79,110,247,.05);
  border-color: rgba(79,110,247,.4);
}
.option:has(input:checked) {
  background: rgba(79,110,247,.07);
  border-color: var(--color-primary);
}

