.option input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  flex-shrink: 0;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background: var(--color-surface);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  position: relative;
  display: grid;
  place-items: center;
