}
.btn-submit:active { transform: translateY(1px); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Status live region ─────────────────────────────────────── */
.status-banner {
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: .95rem;
  border: 1.5px solid;
}
.status-banner--success {
  color: var(--color-success);
