+/* ── Quiz data ────────────────────────────────────────────────
+   Defines the three questions. In a real React app this would
+   live in a data file and be consumed by components via props.
+   ─────────────────────────────────────────────────────────── */
+const QUIZ = [
+  {
+    id: "q1",
+    number: "Question 1 of 3",
+    text: "Which of the following are statically typed languages?",
+    helpId: "q1-help",
+    helpText: "Select all that apply. A statically typed language checks types at compile time rather than at runtime.",
+    options: [
+      { value: "typescript", label: "TypeScript" },
+      { value: "python",     label: "Python"     },
+      { value: "java",       label: "Java"       },
+      { value: "go",         label: "Go"         },
+    ],
+  },
+  {
+    id: "q2",
+    number: "Question 2 of 3",
+    text: "Which languages were originally created at Google?",
+    options: [
+      { value: "go",         label: "Go"         },
+      { value: "dart",       label: "Dart"       },
+      { value: "kotlin",     label: "Kotlin"     },
+      { value: "typescript", label: "TypeScript" },
+    ],
+  },
+  {
+    id: "q3",
+    number: "Question 3 of 3",
+    text: "Which of the following languages are primarily compiled to machine code (not bytecode or a VM)?",
+    options: [
+      { value: "rust",   label: "Rust"   },
+      { value: "csharp", label: "C#"     },
+      { value: "c",      label: "C"      },
+      { value: "java",   label: "Java"   },
+    ],
+  },
+];
+
+
+/* ── Component: CheckboxOption ──────────────────────────────── */
+function CheckboxOption({ questionId, option }) {
+  const inputId = `${questionId}-${option.value}`;
+  const wrapper = document.createElement("div");
+  wrapper.className = "option";
+
+  const input = document.createElement("input");
+  input.type      = "checkbox";
+  input.id        = inputId;
+  input.name      = questionId;
+  input.value     = option.value;
+
+  const label = document.createElement("label");
+  label.htmlFor   = inputId;
+  label.textContent = option.label;
+
+  wrapper.appendChild(input);
+  wrapper.appendChild(label);
+  return wrapper;
+}
+
+
+/* ── Component: QuestionCard ────────────────────────────────── */
+function QuestionCard({ question }) {
+  // .form-field wrapper (required by spec)
+  const card = document.createElement("div");
+  card.className = "form-field";
+  card.dataset.questionId = question.id;
+
+  // <fieldset> groups the checkboxes accessibly
+  const fieldset = document.createElement("fieldset");
+  const describedBy = [];
+  if (question.helpId) describedBy.push(question.helpId);
+  describedBy.push(`${question.id}-error`);
+  fieldset.setAttribute("aria-describedby", describedBy.join(" "));
+
+  // Question number badge (inside legend so AT reads it naturally)
+  const legend = document.createElement("legend");
+  const badge  = document.createElement("span");
+  badge.className   = "question-number";
+  badge.textContent = question.number;
+  legend.appendChild(badge);
+  legend.appendChild(document.createTextNode(question.text));
+
+  fieldset.appendChild(legend);
+
+  // Help text (question 1 only)
+  if (question.helpId) {
+    const help = document.createElement("p");
+    help.id          = question.helpId;
+    help.className   = "help-text";
+    help.textContent = question.helpText;
+    fieldset.appendChild(help);
+  }
+
+  // Options list
+  const optionsList = document.createElement("div");
+  optionsList.className = "options";
+  question.options.forEach(option => {
+    optionsList.appendChild(CheckboxOption({ questionId: question.id, option }));
+  });
+  fieldset.appendChild(optionsList);
+
+  // Error message (hidden until validation fires)
+  const error = document.createElement("p");
+  error.id        = `${question.id}-error`;
+  error.className = "error-text";
+  error.hidden    = true;
+  error.textContent = "Error: Please select at least one answer.";
+  fieldset.appendChild(error);
+
+  card.appendChild(fieldset);
+  return card;
+}
+
+
+/* ── Component: QuizForm ────────────────────────────────────── */
+function QuizForm() {
+  const form = document.createElement("form");
+  form.className    = "quiz-form";
+  form.noValidate   = true;
+  form.setAttribute("aria-label", "Computer Languages Quiz");
+
+  // Render all question cards
+  QUIZ.forEach(question => {
+    form.appendChild(QuestionCard({ question }));
+  });
+
+  // Submit area
+  const submitArea = document.createElement("div");
+  submitArea.className = "submit-area";
+
+  // Live region for overall status message
+  const statusRegion = document.createElement("div");
+  statusRegion.setAttribute("aria-live", "polite");
+  statusRegion.setAttribute("aria-atomic", "true");
+  statusRegion.id = "quiz-status";
+
+  const submitBtn = document.createElement("button");
+  submitBtn.type        = "submit";
+  submitBtn.className   = "btn-submit";
+  submitBtn.textContent = "Submit Quiz";
+
+  submitArea.appendChild(statusRegion);
+  submitArea.appendChild(submitBtn);
+  form.appendChild(submitArea);
+
+  // ── Validation & submit handler ──────────────────────────────
+  form.addEventListener("submit", (e) => {
+    e.preventDefault();
+
+    let firstInvalid = null;
+    let allValid     = true;
+
+    QUIZ.forEach(question => {
+      const card      = form.querySelector(`[data-question-id="${question.id}"]`);
+      const fieldset  = card.querySelector("fieldset");
+      const errorEl   = card.querySelector(`#${question.id}-error`);
+      const checked   = form.querySelectorAll(`input[name="${question.id}"]:checked`);
+
+      if (checked.length === 0) {
+        allValid           = false;
+        card.classList.add("form-field--error");
+        errorEl.hidden     = false;
+        if (!firstInvalid) firstInvalid = fieldset.querySelector("input[type='checkbox']");
+      } else {
+        card.classList.remove("form-field--error");
+        errorEl.hidden = true;
+      }
+    });
+
+    // Clear stale status
+    statusRegion.innerHTML = "";
+    statusRegion.className = "";
+
+    if (!allValid) {
+      firstInvalid.focus();
+      const banner = document.createElement("p");
+      banner.className   = "status-banner status-banner--error";
+      banner.textContent = "Please answer all questions before submitting.";
+      statusRegion.appendChild(banner);
+      return;
+    }
+
+    // Success
+    const banner = document.createElement("p");
+    banner.className   = "status-banner status-banner--success";
+    banner.textContent = "✓ Your answers have been submitted. Thanks for taking the quiz!";
+    statusRegion.appendChild(banner);
+
+    // Optionally disable form after successful submit
+    form.querySelectorAll("input, button").forEach(el => el.disabled = true);
+  });
+
+  // Clear per-field errors as user interacts
+  form.addEventListener("change", (e) => {
+    if (e.target.type !== "checkbox") return;
+    const name    = e.target.name;
+    const card    = form.querySelector(`[data-question-id="${name}"]`);
+    const checked = form.querySelectorAll(`input[name="${name}"]:checked`);
+    if (checked.length > 0) {
+      card.classList.remove("form-field--error");
+      card.querySelector(`#${name}-error`).hidden = true;
+    }
+  });
+
+  return form;
+}
+
+
+/* ── Mount ──────────────────────────────────────────────────── */
+document.addEventListener("DOMContentLoaded", () => {
+  document.getElementById("quiz-root").appendChild(QuizForm());
+});
+
')

