  await page.waitForSelector('.quiz-form', { timeout: 5000 });

  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const results = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = results.violations.filter(v =>  v.tags.includes('best-practice'));

  const fmt = (v) => ({
    id: v.id, impact: v.impact,
    description: v.description,
    targets: v.nodes.map(n => n.target),
    html: v.nodes.map(n => n.html),
  });

  console.log(JSON.stringify({ wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
