*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #f5f6fa;
  --color-surface:      #ffffff;
  --color-border:       #dde1ea;
  --color-border-focus: #1d4ed8;
  --color-primary:      #1d4ed8;
  --color-primary-hover:#1a45c0;
  --color-primary-text: #ffffff;
  --color-text:         #1a1d2e;
  --color-text-muted:   #5a6278;
  --color-help:         #5a6278;
  --color-error:        #c0392b;
  --color-error-bg:     #fdf0ef;
  --color-error-border: #e05c4e;
  --color-success:      #1a7a4a;
  --color-success-bg:   #edfaf3;
  --color-check-bg:     #1d4ed8;
  --color-check-border: #1d4ed8;
  --radius-sm:          6px;
  --radius-md:          12px;
  --radius-lg:          18px;
  --shadow-card:        0 2px 12px rgba(30,40,80,.08), 0 1px 3px rgba(30,40,80,.06);
  --font:               'Inter', system-ui, -apple-system, sans-serif;
  --transition:         150ms ease;
}

/* ── Base ───────────────────────────────────────────────────── */
html { font-size: 100%; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
  line-height: 1.6;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: var(--color-primary-text);
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Layout ─────────────────────────────────────────────────── */
main {
  max-width: 680px;
  margin: 0 auto;
}

/* ── Page header ────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2rem;
}
.page-header__eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: rgba(79,110,247,.1);
  padding: .25rem .75rem;
  border-radius: 999px;
  margin-bottom: .75rem;
}
.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--color-text);
  letter-spacing: -.02em;
}
.page-header__sub {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: .95rem;
}

/* ── Quiz form ──────────────────────────────────────────────── */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Form field card ────────────────────────────────────────── */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 1.5rem 1.75rem;
  transition: border-color var(--transition);
}
.form-field:focus-within {
  border-color: var(--color-border-focus);
}
.form-field--error {
  border-color: var(--color-error-border);
  background: var(--color-error-bg);
}

/* ── Fieldset / legend ──────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}
legend {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: .25rem;
  line-height: 1.4;
  float: left;          /* fix legend inline-block sizing in some browsers */
  width: 100%;
}
legend + * { clear: both; }

.question-number {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: .4rem;
}

/* ── Help & error text ──────────────────────────────────────── */
.help-text {
  font-size: .85rem;
  color: var(--color-help);
  margin-bottom: 1rem;
  line-height: 1.5;
}
.error-text {
  font-size: .85rem;
  color: var(--color-error);
  font-weight: 600;
  margin-top: .75rem;
  display: flex;
  align-items: flex-start;
  gap: .35rem;
}
.error-text::before {
  content: "⚠";
  flex-shrink: 0;
  margin-top: .05em;
}
[hidden] { display: none !important; }

/* ── Checkbox options list ──────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  margin-top: .85rem;
}

/* ── Checkbox option row ────────────────────────────────────── */
.option {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .65rem .9rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  user-select: none;
}
.option:hover {
  background: rgba(79,110,247,.05);
  border-color: rgba(79,110,247,.4);
}
.option:has(input:checked) {
  background: rgba(79,110,247,.07);
  border-color: var(--color-primary);
}

/* ── Custom checkbox ────────────────────────────────────────── */
.option input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  flex-shrink: 0;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background: var(--color-surface);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  position: relative;
  display: grid;
  place-items: center;
}
.option input[type="checkbox"]:checked {
  background: var(--color-check-bg);
  border-color: var(--color-check-border);
}
.option input[type="checkbox"]::after {
  content: "";
  width: .35rem;
  height: .6rem;
  border: 2px solid transparent;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) scale(0);
  transition: transform var(--transition);
}
.option input[type="checkbox"]:checked::after {
  border-color: #fff;
  transform: rotate(45deg) scale(1) translateY(-1px);
}
.option input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Option label ───────────────────────────────────────────── */
.option label {
  font-size: .95rem;
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  flex: 1;
}

/* ── Submit area ────────────────────────────────────────────── */
.submit-area {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 1rem;
  margin-top: .5rem;
}

.btn-submit {
  padding: .75rem 2rem;
  font-size: 1rem;
  font-weight: 700;
  font-family: var(--font);
  color: var(--color-primary-text);
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 2px 8px rgba(79,110,247,.35);
  letter-spacing: .01em;
}
.btn-submit:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 14px rgba(79,110,247,.45);
}
.btn-submit:active { transform: translateY(1px); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Status live region ─────────────────────────────────────── */
.status-banner {
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: .95rem;
  border: 1.5px solid;
}
.status-banner--success {
  color: var(--color-success);
  background: var(--color-success-bg);
  border-color: #6fcf97;
}
.status-banner--error {
  color: var(--color-error);
  background: var(--color-error-bg);
  border-color: var(--color-error-border);
}

/* ── Forced colors (Windows high-contrast) ──────────────────── */
@media (forced-colors: active) {
  .option { border-color: ButtonText; }
  .option:has(input:checked) { background: Highlight; border-color: Highlight; }
  .option input[type="checkbox"] { forced-color-adjust: auto; }
  .btn-submit { forced-color-adjust: none; background: ButtonText; color: ButtonFace; }
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; }
}

/* ── Narrow viewport (320 px reflow) ────────────────────────── */
@media (max-width: 400px) {
  body { padding: 1rem .75rem 3rem; }
  .form-field { padding: 1.25rem 1rem; }
  .submit-area { flex-direction: column; align-items: stretch; }
  .btn-submit { width: 100%; text-align: center; }
}
